/**
 * Error surface for the foreign bindings. Variants mirror the core
 * `Error` taxonomy so Swift/Kotlin catch clauses can branch on the same
 * buckets CLI consumers parse out of the JSON error envelope.
 */
sealed class IntlAiException: kotlin.Exception() {
    
    class Config(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Lockfile(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Io(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Format(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Provider/transport failure; the string is prefixed with the core
     * `ErrorType` (snake_case) and the provider message.
     */
    class Transport(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Caller-side contract violation (e.g. unscoped regenerate without
     * `yes`, judge threshold outside 0..=1).
     */
    class Validation(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Other(
        
        val v1: kotlin.String
        ) : IntlAiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<IntlAiException> {
        override fun lift(error_buf: RustBuffer.ByValue): IntlAiException = FfiConverterTypeIntlAiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeIntlAiError : FfiConverterRustBuffer<IntlAiException> {
    override fun read(buf: ByteBuffer): IntlAiException {
        

        return when(buf.getInt()) {
            1 -> IntlAiException.Config(
                FfiConverterString.read(buf),
                )
            2 -> IntlAiException.Lockfile(
                FfiConverterString.read(buf),
                )
            3 -> IntlAiException.Io(
                FfiConverterString.read(buf),
                )
            4 -> IntlAiException.Format(
                FfiConverterString.read(buf),
                )
            5 -> IntlAiException.Transport(
                FfiConverterString.read(buf),
                )
            6 -> IntlAiException.Validation(
                FfiConverterString.read(buf),
                )
            7 -> IntlAiException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: IntlAiException): ULong {
        return when(value) {
            is IntlAiException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Lockfile -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Format -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Validation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is IntlAiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: IntlAiException, buf: ByteBuffer) {
        when(value) {
            is IntlAiException.Config -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Lockfile -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Io -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Format -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Transport -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Validation -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is IntlAiException.Other -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Per-key outcome of a fill batch (`ProgressEvent::KeyDone`; mirrors
 * `core::progress::KeyOutcome`).
 */
